/**
 * @effects
 *  if n is non-positive
 *    log error and return -1
 *  else
 *    return the factorial of n
 */
public static int computeFact1(int n) {
    try {
        int f = fact(n);
        return f;
    } catch (NonPositiveException e) {
        // log exception
        System.err.println("Error: " + e.getMessage());
        // mask using value -1
        return -1;
    }
}

